style.css:
@-moz-document domain("livechart.me") {
.lc-timetable-anime-block:hover {
    opacity: 1 !important;
  }
  
  .lc-timetable-anime-block[data-library-status=""] {
    opacity: 0.3;
  }
  
  .lc-timetable-anime-block  {
    margin-left: 0.5rem;
  }
  
  .lc-timetable-timeslot__note {
    margin-left: 1rem;
  }
  
  .lc-timetable-anime-block .lc-tt-action-button-wrap {
  margin-left: 0;
      margin-top: 57px;
  }
  
  .lc-timetable-anime-block .lc-tt-action-button-wrap .lc-tt-action-button{
    border-radius: 0 0.5rem  0  4px;
      padding-left: .25rem;
      padding-right: .25rem;
  }
  .lc-timetable-anime-block .lc-tt-action-button-wrap .lc-tt-action-button .lc-icon-masked {
    height: 1rem;
  }
}
